// Cell is one rendered matrix cell: its glyph and the plotext palette colour
// name driving it ("default" / no_color for unstyled cells, "blue+" for bars).
// Returned in display order by [Figure.Cells] so a themed host (the widget) can
// map palette names to theme colours without re-parsing ANSI.
type Cell struct {
	Rune  rune
	Color string // plotext palette colour name, or NoColor
}

// NoColor is the plotext no_color sentinel exposed for callers theming Cells.
const NoColor = noColor

// Cells returns the rendered matrix in display order (top row first), mirroring
// the geometry of Build but as structured cells instead of plotext ANSI. The
// widget uses this to apply theme colours (see the package colour contract).
func (f *Figure) Cells() [][]Cell {
	m := f.buildMatrix()
	out := make([][]Cell, m.rows)
	for r := m.rows - 1; r >= 0; r-- {
		row := make([]Cell, m.cols)
		for c := 0; c < m.cols; c++ {
			row[c] = Cell{Rune: m.marker[r][c], Color: m.fg[r][c]}
		}
		out[m.rows-1-r] = row
	}
	return out
}

